// containsWord returns true if kw appears in s as a whole word/phrase,
// using \b word-boundary matching so that e.g. "test" does not match
// inside "contest". The keyword kw is already lowercased by the caller.
func containsWord(s, kw string) bool {
	if kw == "" {
		return true
	}
	// Escape any regex metacharacters in kw (e.g. "re-factor" contains -).
	// Build the pattern: \b<escaped_kw>\b
	var b strings.Builder
	b.WriteString(`(?i)\b`)
	for _, r := range kw {
		if regexpSpecial(r) {
			b.WriteString(`\`)
		}
		b.WriteRune(r)
	}
	b.WriteString(`\b`)
	matched, _ := regexp.MatchString(b.String(), s)
	return matched
}

// regexpSpecial returns true if rune r is a regex metacharacter that needs
// escaping when building a \b word-boundary pattern.
func regexpSpecial(r rune) bool {
	return r == '\\' || r == '.' || r == '+' || r == '*' || r == '?' ||
		r == '(' || r == ')' || r == '[' || r == ']' || r == '{' ||
		r == '}' || r == '|' || r == '^' || r == '$' || r == '-' || r == '/'
